import{_ as c,C as r,o as l,c as s,j as d,a as e,E as o,a5 as n}from"./chunks/framework.Dep_XxFZ.js";const k=JSON.parse('{"title":"导航菜单","description":"","frontmatter":{},"headers":[],"relativePath":"components/navigation-menu.md","filePath":"components/navigation-menu.md","lastUpdated":1787385783000}'),h={name:"components/navigation-menu.md"},u={id:"导航菜单",tabindex:"-1"};function g(p,t,b,m,v,x){const i=r("Badge"),a=r("XhDemo");return l(),s("div",null,[d("h1",u,[t[0]||(t[0]=e("导航菜单 ",-1)),o(i,{type:"info",text:"navigation-menu"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#导航菜单","aria-label":'Permalink to "导航菜单 <Badge type="info" text="navigation-menu" />"'},"​",-1))]),t[3]||(t[3]=n('<p>站点的主导航：一排入口，展开后是一整块去处面板，面板里是链接不是命令。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>门户、营销站、文档站的顶部导航，每个板块下还有若干去处。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>条目是命令（执行一次动作）：用<a href="./menu">菜单</a>。</li><li>后台的层级导航：用<a href="./side-nav">侧栏导航</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>面板落在同一个 <code>li</code> 里、紧跟入口之后，展开时按 Tab 就走得进去。</li><li><code>delayDuration</code> 防的是指针横穿导航时一路闪出面板；<code>skipDelayDuration</code> 是收起后的静默窗口，窗口内再碰任意入口直接展开。</li><li>没有下级的去处不必套面板：那一项直接铺成一条 <code>link</code>，它不进方向键那一组，按 Tab 一样到得了。</li><li>面板整批塞进 <code>viewport</code> 后落位归外壳管：几个入口的面板落在同一处，宽窄不同也不再各贴各的入口。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>面板落在同一个 li 里、紧跟 trigger 之后，展开时按 Tab 就走得进去，里面的条目是链接不是命令，点了就跳走</p>',10)),o(a,{src:"navigation-menu/01-basic"}),t[4]||(t[4]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[5]||(t[5]=d("p",null,"传了 value 就由宿主说了算，null 表示都收起",-1)),o(a,{src:"navigation-menu/02-controlled"}),t[6]||(t[6]=d("h3",{id:"展开延时",tabindex:"-1"},[e("展开延时 "),d("a",{class:"header-anchor",href:"#展开延时","aria-label":'Permalink to "展开延时"'},"​")],-1)),t[7]||(t[7]=d("p",null,"delay-duration 是悬停多久才展开，防的是指针横穿导航时一路闪出面板；skip-delay-duration 是收起后的静默窗口，窗口内再碰任意入口直接展开",-1)),o(a,{src:"navigation-menu/03-delay"}),t[8]||(t[8]=d("h3",{id:"竖排",tabindex:"-1"},[e("竖排 "),d("a",{class:"header-anchor",href:"#竖排","aria-label":'Permalink to "竖排"'},"​")],-1)),t[9]||(t[9]=d("p",null,'orientation="vertical" 把入口排成一列、面板改从侧边长出来，方向键随之改收上下键',-1)),o(a,{src:"navigation-menu/04-vertical"}),t[10]||(t[10]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[11]||(t[11]=d("p",null,"tone 换的是入口的高亮底与指示条、当前链接的文字色，静止态一样：悬停到入口上、或用方向键把焦点移过去才显现",-1)),o(a,{src:"navigation-menu/05-tone"}),t[12]||(t[12]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=d("p",null,"size 一档换掉入口的高度、内边距与字号，写在 root 上、面板里的链接一并跟着变",-1)),o(a,{src:"navigation-menu/06-size"}),t[14]||(t[14]=d("h3",{id:"直达入口",tabindex:"-1"},[e("直达入口 "),d("a",{class:"header-anchor",href:"#直达入口","aria-label":'Permalink to "直达入口"'},"​")],-1)),t[15]||(t[15]=d("p",null,"没有下级的去处不必套面板：那一项直接铺成一条 link，它不进方向键那一组（那一组只认 trigger），按 Tab 一样到得了",-1)),o(a,{src:"navigation-menu/07-link-item"}),t[16]||(t[16]=d("h3",{id:"共享面板外壳",tabindex:"-1"},[e("共享面板外壳 "),d("a",{class:"header-anchor",href:"#共享面板外壳","aria-label":'Permalink to "共享面板外壳"'},"​")],-1)),t[17]||(t[17]=d("p",null,"面板整批塞进 viewport 后落位归外壳管：几个入口的面板落在同一处，宽窄不同也不再各贴各的入口",-1)),o(a,{src:"navigation-menu/08-viewport"}),t[18]||(t[18]=d("h3",{id:"默认展开项",tabindex:"-1"},[e("默认展开项 "),d("a",{class:"header-anchor",href:"#默认展开项","aria-label":'Permalink to "默认展开项"'},"​")],-1)),t[19]||(t[19]=d("p",null,"defaultValue 只定首帧展开哪一项，之后照常由交互接管；指针移开、Escape 或点回入口都收得起来",-1)),o(a,{src:"navigation-menu/09-default-open"}),t[20]||(t[20]=d("h3",{id:"收窄成一列图标",tabindex:"-1"},[e("收窄成一列图标 "),d("a",{class:"header-anchor",href:"#收窄成一列图标","aria-label":'Permalink to "收窄成一列图标"'},"​")],-1)),t[21]||(t[21]=d("p",null,"竖排时面板本就从入口侧边长出来；收窄只是把文字从入口里撤掉、把它挪进面板，指针停上去才露出来",-1)),o(a,{src:"navigation-menu/10-collapsed"}),t[22]||(t[22]=n('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-navigation-menu&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhNavigationMenuContent</code> <code>XhNavigationMenuIndicator</code> <code>XhNavigationMenuItem</code> <code>XhNavigationMenuLink</code> <code>XhNavigationMenuList</code> <code>XhNavigationMenuRoot</code> <code>XhNavigationMenuTrigger</code> <code>XhNavigationMenuViewport</code></td></tr><tr><td>组合式函数</td><td><code>useNavigationMenu</code></td></tr><tr><td>状态机</td><td><code>navigationMenuMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/navigation-menu.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;navigation-menu&quot;</code>：<strong><code>root</code></strong> · <strong><code>list</code></strong> · <strong><code>item</code></strong> · <code>trigger</code> · <code>content</code> · <strong><code>link</code></strong> · <code>indicator</code> · <code>viewport</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>NavigationMenuNode[]</code></td><td></td><td>入口数据，入口文本与禁用的事实源。给了它，trigger 部件只需报 value。 缺省即回到「文本与禁用都写在部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>当前展开项，给定即受控；null 表示都收起。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>方向键轴向，默认 horizontal。</td></tr><tr><td><code>delayDuration</code></td><td><code>number</code></td><td></td><td>悬停/聚焦到 trigger 后等多久才展开，默认 200ms。</td></tr><tr><td><code>skipDelayDuration</code></td><td><code>number</code></td><td></td><td>收起之后的静默窗口，默认 300ms；窗口内再碰任意 trigger 直接展开。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;NavigationMenuTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: NavigationMenuValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化回调。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>NavigationMenuValueChangeDetails</code></td><td>展开项变化；detail 为 <code>{ value: string | null }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>viewport</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>opening</code> · <code>skipping</code></p><p><strong>事件</strong>：<code>TRIGGER.POINTER</code> · <code>TRIGGER.FOCUS</code> · <code>TRIGGER.TOGGLE</code> · <code>DISMISS</code> · <code>VALUE.SET</code> · <code>after.delayDuration</code> · <code>after.skipDelayDuration</code></p><p><strong>判据</strong>：<code>hasValue</code> · <code>isCurrent</code> · <code>shouldKeepOpen</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useNavigationMenu</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td>当前展开的那一项；都收起时为 null。</td></tr><tr><td><code>collection</code></td><td><code>readonly NavigationMenuNodeMeta[]</code></td><td>collection 推出的入口元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td>有没有面板展开着。</td></tr><tr><td><code>isOpen</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>(props: NavigationMenuTriggerProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>(props: NavigationMenuContentProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLinkProps</code></td><td><code>(props: NavigationMenuLinkProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/examples/disclosure-navigation/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in trigger, 按键与 orientation 同轴</td><td>焦点移到下一个 trigger（禁用项跳过、尽头按 loop 回绕）；随后的自动展开走 delayDuration</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in trigger, 按键与 orientation 同轴</td><td>焦点移到上一个 trigger</td></tr><tr><td><code>Home</code></td><td>focus in trigger</td><td>焦点移到首个可停留 trigger</td></tr><tr><td><code>End</code></td><td>focus in trigger</td><td>焦点移到末个可停留 trigger</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger, not disabled</td><td>立即展开对应面板（不走 delayDuration）；面板是自动弹出来的那一次不收起，再按一次才收起</td></tr><tr><td><code>Escape</code></td><td>open</td><td>收起面板并把焦点归还对应 trigger；静默窗口内这一次归还不会把面板重新弹出来</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>open, focus in trigger</td><td>走进展开的面板：面板就在 trigger 之后，收起的面板带 hidden 因而被整个跳过</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.translations.root</td></tr><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>trigger</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>link</code></td><td><code>aria-current</code></td><td>&#39;page&#39; | undefined</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/navigation-menu.css</code> 按部件选择：<code>[data-scope=&quot;navigation-menu&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>list</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>link</code></td><td><code>data-current</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td><code>data-value</code></td><td>context.get(&#39;value&#39;)</td></tr><tr><td><code>viewport</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>viewport</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-navigation-menu-content-bg</code> · <code>--xh-navigation-menu-content-border</code> · <code>--xh-navigation-menu-content-gap</code> · <code>--xh-navigation-menu-content-min-w</code> · <code>--xh-navigation-menu-content-offset</code> · <code>--xh-navigation-menu-content-p</code> · <code>--xh-navigation-menu-content-radius</code> · <code>--xh-navigation-menu-content-shadow</code> · <code>--xh-navigation-menu-fg</code> · <code>--xh-navigation-menu-font-size</code> · <code>--xh-navigation-menu-gap</code> · <code>--xh-navigation-menu-indicator-color</code> · <code>--xh-navigation-menu-indicator-radius</code> · <code>--xh-navigation-menu-indicator-thickness</code> · <code>--xh-navigation-menu-layer</code> · <code>--xh-navigation-menu-link-bg-hover</code> · <code>--xh-navigation-menu-link-fg</code> · <code>--xh-navigation-menu-link-fg-current</code> · <code>--xh-navigation-menu-link-font-size</code> · <code>--xh-navigation-menu-link-font-weight-current</code> · <code>--xh-navigation-menu-link-px</code> · <code>--xh-navigation-menu-link-py</code> · <code>--xh-navigation-menu-link-radius</code> · <code>--xh-navigation-menu-trigger-bg-active</code> · <code>--xh-navigation-menu-trigger-bg-hover</code> · <code>--xh-navigation-menu-trigger-fg</code> · <code>--xh-navigation-menu-trigger-font-weight</code> · <code>--xh-navigation-menu-trigger-gap</code> · <code>--xh-navigation-menu-trigger-h</code> · <code>--xh-navigation-menu-trigger-px</code> · <code>--xh-navigation-menu-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./layout">布局</a>的头部配合；窄屏时整体换成<a href="./drawer">抽屉</a>里的<a href="./side-nav">侧栏导航</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>面板里的链接分组并加组标题，一整块无结构的链接墙没人看得下去。</li><li>延时保留默认值：调到 0 会让导航在指针路过时不停闪。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>面板里混进需要提交的表单或命令按钮。</li><li>悬停即刻展开且没有静默窗口：指针横穿时面板一路弹出。</li></ul>',45))])}const P=c(h,[["render",g]]);export{k as __pageData,P as default};
